// Extra Territorial Enterprise story leads for Roughing It. Written for this game.
// Fields: name, text, base (reader appeal), risk (trouble), s (if stretched), w (if a whopper), pay (a grateful party tips you).
window.EXTRA_LEADS = [
  {"id":"m01","name":"The assayer who never says no","text":"An assayer on B Street has returned a rich result on every sample brought to him this month, including, by one account, a lump of cornbread.","base":18,"risk":10,"s":"You report the cornbread ran forty dollars a ton, and a bakery files a claim.","w":"You print his certificate for a brick from the courthouse, and the county is offered for sale in San Francisco by noon."},
  {"id":"m02","name":"A salted mine on Six-Mile Canyon","text":"Investors from Sacramento bought a claim after finding gold dust in every pan. It now appears the dust was fired into the rock from a shotgun.","base":17,"risk":12,"s":"You note the seller has since gone into the shotgun business.","w":"You report the ledge was so rich it had birdshot in it, and three hunters stake claims on a duck."},
  {"id":"m03","name":"Heat on the lower levels","text":"Miners on the deepest level of the Ophir work in water hot enough to boil an egg, and take their breaks in an ice room the company keeps below.","base":14,"risk":4,"s":"You add that the foreman’s coffee boils in his pocket.","w":"You report a miner was sent down raw and came up medium-rare, and the boarding houses ask for the recipe."},
  {"id":"m04","name":"The superintendent’s new carriage","text":"The superintendent of a mine that has not paid a dividend in a year has bought a carriage with silver lamps and a coachman in gloves.","base":15,"risk":18,"s":"You wonder in print which dividend the lamps were paid from.","w":"You report the shareholders are being invited to ride behind it on foot, at an assessment of two dollars a mile."},
  {"id":"m05","name":"Claim jumpers on Cedar Hill","text":"Two parties claim the same forty feet. Both have notices, both have shotguns, and both have taken up residence in the same tent.","base":16,"risk":8,"s":"You report they now take turns sleeping, and turns guarding the coffee.","w":"You report they have married into each other’s families to settle the title, and a lawyer weeps."},
  {"id":"m06","name":"A stamp mill goes quiet","text":"For the first time in a year the stamp mill below town stopped for a whole afternoon. Residents woke from naps, alarmed, thinking they had gone deaf.","base":13,"risk":3,"s":"You report a doctor treated eleven people for silence.","w":"You report the town held a prayer meeting until the stamps started again, then slept like babies."},
  {"id":"m07","name":"The Eastern capitalist","text":"A gentleman from Boston in a silk hat is touring the mines with a notebook and a great willingness to be told things.","base":16,"risk":9,"s":"You note he has bought feet in four mines and one mine that is a hole a dog dug.","w":"You report he purchased the Washoe Zephyr outright and is shipping it to Boston for the summer."},
  {"id":"m08","name":"Assessment notices again","text":"The Grand Bilk Consolidated has levied its ninth assessment on shareholders. It has produced no ore but a great deal of handsome stationery.","base":14,"risk":16,"s":"You estimate the stationery assays at eight dollars a ream.","w":"You report the company has struck a rich vein of letterhead at the four-hundred-foot level."},
  {"id":"m09","name":"A strike at the Belcher","text":"Word is that the Belcher has broken into a body of ore at the lower level. The owners would very much like it written up.","base":17,"risk":7,"pay":true,"s":"You call it the richest ore since the Ophir and the owners send cigars.","w":"You report the ore is so rich the miners have to wear smoked spectacles, and the stock doubles before lunch."},
  {"id":"m10","name":"The mule that knows the tunnel","text":"A mule in the Gould & Curry has worked underground so long it refuses to come up, and stamps a hoof at daylight.","base":15,"risk":2,"s":"You report it has been offered a position as shift boss.","w":"You report the mule now votes in the miners’ union and carried the last election."},
  {"id":"m11","name":"A tunnel to drain the Comstock","text":"An engineer proposes a tunnel four miles long through the mountain to drain the mines of their hot water. He is raising money for it in every saloon.","base":13,"risk":6,"s":"You report it will be finished in time for the engineer’s great-grandchildren.","w":"You report the tunnel will come out in China and the engineer is learning the language."},
  {"id":"m12","name":"Fire in the timbering","text":"Smoke has been seen coming from a ventilation shaft. The company says it is nothing. The miners have come up anyway.","base":15,"risk":14,"s":"You note that “nothing” has burned for two days.","w":"You report the mine is now being used to roast coffee for the whole town, at a profit."},
  {"id":"m13","name":"The square-set timber man","text":"A German engineer’s new method of timbering the mines in boxes like a honeycomb has made the deep levels safe enough to stand in.","base":11,"risk":3,"pay":true,"s":"You call him the most useful man in the Territory, and a mine sends feet.","w":"You report he has timbered a whole mountain and the mountain feels much better."},
  {"id":"m14","name":"A miner’s wager on the hoist","text":"Two miners bet on who could ride the hoisting cage down faster. Both won, and both are in bed.","base":13,"risk":5,"s":"You report they arrived before they left.","w":"You report one went so fast he came out the bottom in the Sandwich Islands and wrote home."},
  {"id":"m15","name":"The Wide West feet war","text":"Shares in the Wide West rose eleven dollars on a rumour and fell twelve on another rumour about the first one.","base":14,"risk":10,"s":"You trace both rumours to the same barber.","w":"You report the barber now controls the market and is buying up the mountain one shave at a time."},
  {"id":"m16","name":"A man who owns nothing but feet","text":"A prospector claims to own feet in sixty-one mines and no socks. He has offered to pay his hotel bill in shares.","base":16,"risk":4,"s":"You report the hotel accepted and now owns a ledge it cannot find.","w":"You report the hotel has been paid so often in feet that it walked off down C Street."},
  {"id":"m17","name":"A cave-in nobody minded","text":"Part of an old drift collapsed in an abandoned claim on Gold Hill. Nobody was hurt, and two men tried to sell the hole.","base":12,"risk":3,"s":"You report the hole is quoted at forty cents a foot.","w":"You report the hole has been incorporated with a capital stock of a million dollars."},
  {"id":"m18","name":"The ore thief’s lunch pail","text":"A watchman caught a miner leaving with a lunch pail that weighed forty pounds. It contained a sandwich and a remarkable amount of rock.","base":14,"risk":7,"s":"You report it was the heaviest sandwich in Nevada.","w":"You report the man claims he simply ate a very rich breakfast underground."},
  {"id":"m19","name":"The richest mine in the world, again","text":"The new owners of the Hale & Norcross call it the richest mine in the world. So did the last owners, before they sold.","base":13,"risk":12,"pay":true,"s":"You call it the richest mine in the world this week.","w":"You report it is so rich the owners pave their hallways with ore and the mice go about with picks."},
  {"id":"m20","name":"A dog that found a ledge","text":"A miner’s dog dug up a vein of quartz behind a boarding house. The dog has been named as a partner.","base":18,"risk":2,"s":"You report the dog is holding out for a larger share.","w":"You report the dog has sold out to a San Francisco syndicate and retired to a better class of fleas."},
  {"id":"m21","name":"The doubtful assay of Professor Fudd","text":"A visiting professor has published a pamphlet proving there is no silver on the Comstock, by careful reasoning. He was standing on some at the time.","base":15,"risk":10,"s":"You invite him underground to be disproved personally.","w":"You report he has since assayed the moon and found it, too, entirely unpromising."},
  {"id":"m22","name":"Water in the Savage","text":"A flood on the lower level has stopped work in the Savage. The pumps run day and night, and the water seems to like it there.","base":12,"risk":9,"s":"You suggest the company sell the water to the dry saloons.","w":"You report a steamboat has been ordered to run excursions on the eight-hundred-foot level."},
  {"id":"m23","name":"The hoisting engineer’s bell","text":"The engineer at the hoist answers bell signals from below. Someone rang for “whiskey” as a joke, and the cage came up with a bottle.","base":15,"risk":4,"s":"You report the signal has been added to the official code.","w":"You report a bell code for “a raise in wages” was also tried, and the cage did not move."},
  {"id":"m24","name":"A mine sold three times","text":"The same claim in American Flat has been sold to three different buyers this month, all by the same cheerful man, all for cash.","base":16,"risk":13,"s":"You report the man is now buying it back from the second buyer to sell to a fourth.","w":"You report the buyers met at the claim and formed a church."},
  {"id":"m25","name":"Croppings in the cemetery","text":"A prospector has found promising quartz in the town cemetery and wants to stake a claim. The residents have not objected.","base":14,"risk":15,"s":"You report the residents are taking the news remarkably calmly.","w":"You report two of them have already filed counter-claims."},
  {"id":"m26","name":"The superintendent explains","text":"A mine superintendent calls at the office to explain that his mine’s fall in price is due to the phase of the moon and a conspiracy of jealous mules.","base":13,"risk":16,"s":"You print his explanation word for word, with no comment, which is worse.","w":"You report he has sued the moon, and the moon is expected to settle."},
  {"id":"m27","name":"A new quartz crusher","text":"An inventor has built a machine he says crushes ore twice as fast as any stamp mill. It is mostly made of bedsteads.","base":12,"risk":4,"s":"You report it crushed its inventor’s confidence in eleven minutes.","w":"You report it crushed a mountain, three wagons and a passing politician."},
  {"id":"m28","name":"A miners’ union picnic","text":"The miners’ union held its picnic on the hill. There were sack races, speeches, and a fight that was very well attended.","base":12,"risk":6,"s":"You report the fight drew a larger crowd than the speeches.","w":"You report the fight lasted three days and was entered in the territorial record as a holiday."},
  {"id":"m29","name":"Silver bricks on the stage","text":"The weekly bullion stage left for San Francisco carrying silver bricks worth a fortune and one very nervous guard.","base":14,"risk":8,"s":"You report the guard has now checked the bricks two hundred times.","w":"You report road agents read about the load and sent a polite note asking for directions."},
  {"id":"m30","name":"A ledge under C Street","text":"Miners following a vein have tunnelled under C Street, and on a quiet night shopkeepers can hear blasting under their floors.","base":16,"risk":7,"s":"You report one saloon’s piano now plays itself during shifts.","w":"You report a whole block of C Street dropped eight inches and the residents felt shorter."},
  {"id":"m31","name":"The prospector’s divining rod","text":"An old prospector finds ore with a forked hazel stick and has never made a cent. He says the stick is fine and the ledges are lying.","base":14,"risk":2,"s":"You report the stick has been offered a job at the Ophir.","w":"You report the stick discovered a ledge, staked it, and refused to share."},
  {"id":"m32","name":"A stock certificate with no mine","text":"A handsome stock certificate is circulating for the Golden Fleece Mining Company. Nobody has found the Golden Fleece, or the company.","base":15,"risk":11,"s":"You note the name may be more accurate than intended.","w":"You report the mine is located on a cloud above Mount Davidson and has very good drainage."},
  {"id":"m33","name":"The shift whistle","text":"The mine whistles all blow at slightly different times, and the town has given up agreeing what o’clock it is.","base":11,"risk":3,"s":"You report it is now three different noons in Virginia City.","w":"You report a man got married at one noon and divorced by another before supper."},
  {"id":"m34","name":"Miner rescues a cat","text":"A miner climbed down two hundred feet into an abandoned shaft to rescue a kitten. The kitten climbed out on its own before he reached it.","base":17,"risk":2,"s":"You report the kitten waited at the top to supervise his ascent.","w":"You report the kitten has been made a superintendent on the grounds of experience."},
  {"id":"m35","name":"The great dividend","text":"A mine has actually paid a dividend. Shareholders who had forgotten they owned it are coming into town to look at it.","base":15,"risk":5,"pay":true,"s":"You call it the most dependable property in Washoe, and the owners are grateful.","w":"You report the dividend was so large it was paid in wagons, and the mules had to be paid too."},
  {"id":"m36","name":"Speculators at the brokers’","text":"A crowd of speculators stood all day outside the brokers’ windows on C Street, shouting prices at each other.","base":12,"risk":6,"s":"You report three men lost fortunes they had made that morning.","w":"You report one man was so rich at ten and so poor at four that he had to borrow his own hat."},
  {"id":"m37","name":"A mine named for a mother-in-law","text":"A prospector named his new claim after his mother-in-law, on the grounds that it is hard, cold and full of surprises.","base":17,"risk":9,"s":"You report she has read it and is coming to inspect the claim.","w":"You report the claim has caved in out of sheer offence."},
  {"id":"m38","name":"Candles underground","text":"The candle bill for the mines this year would light Boston for a decade. One superintendent wants to train glow-worms.","base":11,"risk":3,"s":"You report the glow-worms have asked for union wages.","w":"You report the worms struck for shorter hours and won."},
  {"id":"m39","name":"A suspicious lawsuit","text":"The Chollar and the Potosi are in court again over where one ledge ends and the other begins. The lawyers are the only ones striking pay dirt.","base":14,"risk":15,"s":"You estimate the lawyers have mined more silver than either company.","w":"You report the ledge has hired its own lawyer and is suing both of them."},
  {"id":"m40","name":"The Comstock rumbles","text":"A heavy blast underground shook the windows of half the town. A bishop dropped his teacup and has not yet forgiven the Ophir.","base":14,"risk":8,"s":"You report the teacup is recovering and the bishop is not.","w":"You report the blast moved the town six feet west and nobody has had the courage to move it back."},
  {"id":"m41","name":"A woman prospector","text":"A widow from Ohio has staked a claim on her own, works it with her own hands, and has outdug every man on her hill.","base":16,"risk":5,"s":"You report her neighbours have asked her for lessons.","w":"You report she has dug clear through the hill and is now selling tickets to see out the other side."},
  {"id":"m42","name":"Ore wagons on the grade","text":"An ore wagon with eight mules lost its brakes on the Geiger Grade and went down the hill at a speed never before achieved by mules.","base":15,"risk":4,"s":"You report the mules beat the telegraph to Reno.","w":"You report the mules were last seen in Sacramento demanding a raise."},
  {"id":"m43","name":"The ventilation fan","text":"A mine has installed a huge fan to blow fresh air into the lower levels. It blew a superintendent’s hat into the next county.","base":12,"risk":5,"s":"You report it has outdone the Washoe Zephyr on a still day.","w":"You report it blew the mine dry, the miners bald, and a squirrel to Utah."},
  {"id":"m44","name":"A rich man’s tunnel to nowhere","text":"A millionaire is driving a tunnel into Mount Davidson for no known reason. His men are paid well and asked no questions.","base":13,"risk":10,"s":"You guess he is looking for the money he spent on it.","w":"You report he means to come out under his rival’s house and borrow the silverware."},
  {"id":"m45","name":"The quartz that glowed","text":"A miner brought in a lump of quartz that seems to glow at night. Assay unknown. Several men have already sold their mines to buy feet in it.","base":15,"risk":7,"s":"You report it has been used as a night lamp by the man’s wife.","w":"You report it was a lantern somebody dropped in a drift, still lit."},
  {"id":"m46","name":"Bonanza or borrasca","text":"A mine that was in “bonanza” last week is now in “borrasca”, the miners’ word for when the ore runs out and so do the shareholders.","base":12,"risk":11,"s":"You report the shareholders have gone into borrasca too.","w":"You report the superintendent has gone into borrasca in Mexico with the payroll."},
  {"id":"m47","name":"The new hoisting cable","text":"A mine has replaced its hemp rope with wire cable, and miners now ride the cage singing hymns of gratitude.","base":11,"risk":3,"pay":true,"s":"You praise the company’s care for its men and receive a box of cigars.","w":"You report the cable is so strong it lifted the whole mountain an inch to test it."},
  {"id":"m48","name":"A burro goes into business","text":"A burro wandered off with a prospector’s pack and came back two days later with a sample of very rich ore. The prospector is following it.","base":18,"risk":2,"s":"You report the burro refuses to say where.","w":"You report the burro has filed a claim in its own name and hired the prospector."},
  {"id":"m49","name":"The ten-stamp mill with nine","text":"A mill advertised as ten-stamp has nine stamps and a large man who stands at the end hitting rocks with a hammer.","base":16,"risk":6,"s":"You report the large man is the most productive stamp.","w":"You report the mill has upgraded to twenty stamps by hiring his brothers."},
  {"id":"m50","name":"An expert from Freiberg","text":"A mining expert trained in Germany has arrived to examine the Comstock. He says “very interesting” about everything, which costs a hundred dollars a day.","base":13,"risk":9,"s":"You calculate his “very interesting” at twelve dollars a syllable.","w":"You report he said something other than “very interesting” on Tuesday, and three mines failed."},
  {"id":"m51","name":"A prospector’s will","text":"An old prospector has left his estate to his favourite mule, his pick to the town, and his feet in eleven mines to anyone who can find them.","base":15,"risk":3,"s":"You report three hundred people are now looking for them.","w":"You report the mule has hired a lawyer and contested the pick."},
  {"id":"m52","name":"The ore the company forgot","text":"Miners clearing an old drift found a pile of rich ore that the company had mined three years ago and forgotten about.","base":14,"risk":7,"pay":true,"s":"You call the company thrifty for keeping it so long.","w":"You report the company has found several other forgotten things, including a superintendent."},
  {"id":"m53","name":"Blasting powder in the boarding house","text":"A miner has been storing his blasting powder under his bed at the boarding house. His landlady has found out.","base":14,"risk":5,"s":"You report the landlady was the bigger explosion.","w":"You report the landlady now stores the powder and the miner sleeps in the street."},
  {"id":"m54","name":"Mexican Plug in the mine","text":"A horse has fallen down an abandoned shaft and is standing at the bottom, unhurt, eating hay that is lowered to it in a bucket.","base":16,"risk":2,"s":"You report it seems happier than it has ever been on the surface.","w":"You report the horse has refused rescue and asked for its mail to be sent down."},
  {"id":"m55","name":"A visiting senator underground","text":"A senator from the East went down into the Ophir to see the works, and came up with a great many opinions and a burned hat.","base":14,"risk":17,"s":"You report his opinions were hotter than the lower level.","w":"You report he gave a two-hour speech at the twelve-hundred-foot level and the miners begged to go back to work."},
  {"id":"t01","name":"A tragedian comes to Maguire’s","text":"A touring tragedian from New York opens in Hamlet at the opera house. He has played it four hundred times and appears to remember about half.","base":14,"risk":10,"s":"You report that the ghost got the biggest laugh, and the tragedian sends round a note in iambic pentameter calling you a varlet.","w":"Your review has Hamlet forgetting his lines so long that the prompter finished the play alone; the prompter is now booked for a tour."},
  {"id":"t02","name":"Mrs. Halloran’s boarding-house hash","text":"The boarders at Mrs. Halloran’s on B Street have held a meeting about the hash. The hash was not consulted.","base":12,"risk":9,"s":"You describe the hash as having a long and varied past, and Mrs. Halloran serves you a double portion out of spite.","w":"In print the hash files a counter-petition and is elected chairman; three boarders move out and one asks to marry the cook."},
  {"id":"t03","name":"A dog that attends every fire","text":"A yellow dog named Bummer has turned out for every fire alarm this year, usually ahead of the engine. The fire company is considering giving him a hat.","base":13,"risk":3,"s":"You call Bummer the most reliable public servant in the Territory, and the fire chief stops speaking to you.","w":"You report that Bummer put out the Sutton Avenue fire himself with a bucket; children leave him sausages for a week."},
  {"id":"t04","name":"The Zephyr takes a church steeple","text":"The afternoon Zephyr lifted the steeple off the Methodist church and set it down, very gently, on a saloon.","base":15,"risk":6,"s":"You note that the saloon has seen better attendance since, and both congregations write letters.","w":"Your account has the steeple ringing its bell over the bar every hour; the saloon keeper hires a choir and the minister demands rent."},
  {"id":"t05","name":"A wager on the weather","text":"Two old-timers at the International Hotel have bet a hundred dollars on whether it will snow before Thanksgiving. Both have consulted their knees.","base":9,"risk":4,"s":"You print the odds as offered by each knee, and the town begins betting on the knees.","w":"You report that one man has hired a Paiute rainmaker and the other a brass band to frighten clouds; both deny it loudly, which helps."},
  {"id":"t06","name":"A newcomer in a silk hat","text":"A young man from Boston stepped off the stage this morning in a silk hat, kid gloves and an air of having arrived somewhere important.","base":11,"risk":7,"s":"You describe his hat’s first encounter with the Zephyr, and he calls on the office to complain, hatless.","w":"Your piece has the hat chased to Gold Hill by a mob of admirers and elected to the school board; the young man leaves on the next stage."},
  {"id":"t07","name":"The barber who talks","text":"Professor Duval, the C Street barber, has taken to delivering lectures on astronomy while shaving. Customers say he is good on the planets and dangerous near the ears.","base":10,"risk":8,"s":"You advise readers to bring their own ears, and the Professor’s trade doubles out of curiosity.","w":"In your version he shaved a man clean through a lunar eclipse without looking; three astronomers write in to ask for appointments.","pay":true},
  {"id":"t08","name":"A painless dentist arrives","text":"A dentist calling himself Doctor Painless has set up over the drugstore with a chair, a pair of pliers and a banner.","base":12,"risk":10,"s":"You report that the banner is the most painless thing on the premises, and patients start arriving drunk to be safe.","w":"You claim he pulled a tooth so fast the patient is still waiting for it to hurt; the doctor frames the clipping and doubles his fee.","pay":true},
  {"id":"t09","name":"Runaway mule on C Street","text":"A freight mule broke loose this morning and toured C Street, visiting three saloons, a bank and the Methodist Sunday school before being caught.","base":14,"risk":3,"s":"You write that the mule was the only visitor to all four establishments and was welcome at none.","w":"Your mule opens an account at the bank and is invited to stand for the legislature; the owner now charges admission to see him."},
  {"id":"t10","name":"The Engine Company ball","text":"Engine Company No. 2 is giving its grand annual ball. Last year’s ended with a fist fight and a proposal of marriage, in that order.","base":12,"risk":9,"s":"You predict this year’s will run the other way round, and both are achieved by midnight.","w":"Your report has the firemen putting out the chandeliers between waltzes; Engine Company No. 1 demands equal coverage of its own fire."},
  {"id":"t11","name":"A wedding in a mine","text":"A miner and a schoolteacher are to be married eight hundred feet down in the Savage, by lamplight, because that is where they met.","base":16,"risk":4,"s":"You call it the deepest marriage in the Territory, and the couple ask for twenty copies.","w":"You report the vows were drowned out by a blast and nobody is sure who married whom; four couples claim the license."},
  {"id":"t12","name":"The hotel’s new bill of fare","text":"The International Hotel has printed a bill of fare in French. Nobody in the kitchen speaks French, including the cook, who is from Ohio.","base":11,"risk":8,"s":"You translate the menu literally, and the hotel’s ox-tail soup becomes a local joke.","w":"In print the cook serves a dish called “a l’Ohio” that causes a Frenchman to weep; the hotel adds it to the menu permanently.","pay":true},
  {"id":"t13","name":"A christening with cannon","text":"A Gold Hill family christened their first child with a sermon, a brass band and a salute from the militia’s brass cannon.","base":10,"risk":5,"s":"You write that the baby slept through the cannon but woke for the sermon, and the minister takes it personally.","w":"Your account has the cannon ball still somewhere over Utah, carrying the baby’s name; the family is delighted."},
  {"id":"t14","name":"The schoolmaster’s spelling bee","text":"The schoolmaster has challenged the town to a public spelling bee, and the editors of both papers have been asked to compete.","base":15,"risk":12,"s":"You report that the rival editor was spelled down on “cat”, and he challenges you to “dictionary”.","w":"Your version has the schoolmaster losing to a parrot; the parrot is offered the post of city editor and very nearly takes yours."},
  {"id":"t15","name":"A lost Newfoundland","text":"A large Newfoundland dog, answers to Captain, has gone missing. His owner offers ten dollars and says the dog is smarter than most aldermen.","base":9,"risk":7,"s":"You print the description and the comparison with the aldermen, and the aldermen ask for a correction.","w":"You report Captain was seen sitting in on the council meeting and voting; the council asks you to stop, and the dog to keep coming."},
  {"id":"t16","name":"Ice cream at last","text":"An enterprising man has brought ice down from the Sierra by mule and opened Virginia City’s first ice cream saloon.","base":13,"risk":3,"s":"You call it the coldest thing on the Comstock after a mining director’s heart, and the line goes round the block.","w":"Your article claims the ice cream froze a man to his chair for a week; the proprietor sells out by noon.","pay":true},
  {"id":"t17","name":"A ghost at the Gould & Curry","text":"The night shift swears a ghost walks the 600-foot level, carrying a candle and asking the time.","base":16,"risk":6,"s":"You report that the ghost is the only man underground who cares what time it is, and the foreman denies everything.","w":"In your account the ghost files a claim on the 600-foot level and is upheld in court; the superintendent hires a priest and a lawyer."},
  {"id":"t18","name":"The minstrel show from San Francisco","text":"A minstrel troupe from San Francisco plays three nights at the opera house. The banjo player is said to be very good; the jokes are said to be very old.","base":10,"risk":7,"s":"You date the jokes by their geology, and the troupe drops two of them.","w":"You report a joke so old it was found petrified in the Ophir; the troupe sues for the fossil rights."},
  {"id":"t19","name":"A saloon with a library","text":"The Delta saloon has installed a shelf of books, mostly sermons left by a departed boarder. The patrons are said to be reading them.","base":11,"risk":6,"s":"You call it the most improving bar in the Territory, and the temperance society holds a meeting there.","w":"Your piece has a faro dealer converted by page forty and dealing only honest hands; the Delta loses money for the first time."},
  {"id":"t20","name":"The Zephyr and the washing","text":"The Zephyr carried off every shirt drying on the lines of B Street and redistributed them up the mountain.","base":12,"risk":4,"s":"You report that half of Gold Hill is wearing the other half’s shirts and nobody is sure whose are whose.","w":"In your account a line of laundry was seen sailing over Carson like a flag; the Governor saluted it."},
  {"id":"t21","name":"A doctor’s new electrical cure","text":"Doctor Ferris has a galvanic machine he says cures rheumatism, baldness, and low spirits by means of shocks at a dollar a turn.","base":12,"risk":11,"s":"You test it and report that it cures everything except the desire to try it again.","w":"Your account has a bald customer leaving with a full head of hair standing straight up; the line stretches to Gold Hill.","pay":true},
  {"id":"t22","name":"The stage arrives seven hours late","text":"The overland stage came in seven hours late with a broken wheel, a lame horse, and a passenger who has not stopped talking since Placerville.","base":9,"risk":5,"s":"You interview the passenger and the horse, and print the horse’s account as more reliable.","w":"You report the passenger talked the coach the last ten miles on his own steam; the stage company offers him a job."},
  {"id":"t23","name":"A town election for dogcatcher","text":"The race for town dogcatcher has turned bitter. One candidate owns six dogs; the other says he has never met one.","base":13,"risk":13,"s":"You call it the only election in the Territory where the voters bite, and both candidates claim your endorsement.","w":"Your report has the dogs holding a rally for their candidate; the other side accuses you of stuffing the kennel."},
  {"id":"t24","name":"Fourth of July oration","text":"The Fourth of July orator talked for two hours and forty minutes, and the brass band began playing during the third hour in self-defence.","base":11,"risk":10,"s":"You print the oration in full, then a summary, then a summary of the summary, which is “hooray”.","w":"You claim three listeners grew beards during the speech; the orator calls at the office to begin a longer one."},
  {"id":"t25","name":"Boarding-house piano","text":"A boarder at the Widow Grimes’s has bought a piano and plays only one tune. Eleven other boarders have petitioned to buy him a second one.","base":10,"risk":6,"s":"You reproduce the tune in print as a single repeated line, and someone starts whistling it in the street.","w":"Your piece has the tune driving a mule to sign the pledge; the whole town is humming it by Friday."},
  {"id":"t26","name":"A wager on the hill climb","text":"A Gold Hill man has bet he can push a wheelbarrow of quartz up the Geiger Grade in under an hour. Half the county is going to watch.","base":15,"risk":5,"s":"You report the finishing time and that the wheelbarrow looked fresher, and he asks for a rematch with the wheelbarrow.","w":"In your account he arrived at the top so fast the quartz assayed richer; three mining companies want to hire the wheelbarrow."},
  {"id":"t27","name":"Theatre fire scare","text":"Someone shouted “fire” during the second act of the melodrama. It was the actor playing the villain, who had been told to and forgot what came next.","base":13,"risk":8,"s":"You call it his finest line of the evening, and the leading lady agrees in a letter.","w":"You report the audience was out on C Street before the curtain finished falling and three fire companies played on the villain; he is booked for a revival."},
  {"id":"t28","name":"The ladies’ sewing circle feud","text":"The ladies’ sewing circle has split into two circles over the colour of a quilt. Both quilts are now being sewn faster than ever.","base":12,"risk":17,"s":"You describe the split as the second most serious division in the nation, and both circles cancel your subscription.","w":"Your report has the quilts meeting on C Street at dawn for a duel; your landlady belongs to one circle and you eat cold supper for a month."},
  {"id":"t29","name":"A Chinese New Year procession","text":"The Chinese quarter celebrated the New Year with a procession, firecrackers by the thousand, and a dragon forty feet long. The whole town turned out to watch.","base":14,"risk":5,"s":"You write that it was the only parade in town that did not stop at a saloon, and the merchants send round a box of tea.","w":"Your account has the dragon chasing off the Zephyr for a whole afternoon; the town council asks if it can be hired for August."},
  {"id":"t30","name":"A camel loose in Carson","text":"One of the old army camels, left over from a freight scheme, got loose in Carson and frightened every horse in the county into the next.","base":15,"risk":4,"s":"You report the horses have not forgiven the camel, and the camel does not care.","w":"In your account the camel walked into the legislature and was mistaken for a member; it voted twice and was not caught."},
  {"id":"t31","name":"Hotel chambermaid’s thrift","text":"A chambermaid at the Ormsby House has saved her wages, bought ten feet in a wildcat mine, and is now worth more than the hotel.","base":13,"risk":5,"s":"You note that she still makes the beds, and three guests propose.","w":"Your report has her buying the hotel and hiring the proprietor to make the beds; he does it badly."},
  {"id":"t32","name":"The church social raffle","text":"The Presbyterian social raffled a cake, a quilt and a pig. The pig was won by the minister, who is not sure what to do with it.","base":10,"risk":7,"s":"You suggest a christening, and the minister preaches on the subject of newspapers.","w":"You report the pig has joined the choir and is the only member on key; the choir resigns in a body."},
  {"id":"t33","name":"Snow in June","text":"It snowed for twenty minutes yesterday, in June, and then the sun came out as if nothing had happened.","base":8,"risk":2,"s":"You describe the Washoe climate as having a sense of humour, and an old-timer calls that an understatement.","w":"Your piece has a man shovelling snow off his porch and getting sunburnt in the same quarter-hour; Eastern papers reprint it as weather data."},
  {"id":"t34","name":"A gambler’s funeral","text":"Faro Pete has died of nothing in particular, and his friends have arranged a send-off with a band, eleven carriages and a deck of cards in the coffin.","base":14,"risk":8,"s":"You note that Pete was laid out with an ace up his sleeve out of respect for his habits, and his friends nod gravely.","w":"Your account has Pete winning the last hand at the graveside; the minister asks for a share."},
  {"id":"t35","name":"The Gold Hill brass band","text":"The Gold Hill brass band has a new tuba and is practising every evening. Several dogs have left town.","base":9,"risk":6,"s":"You review the band by listing which dogs have left, and the bandleader asks for the names.","w":"You report the tuba blew a hole in the Zephyr and let a whole afternoon of calm through; the band is hired by the hotels."},
  {"id":"t36","name":"An auction of unclaimed baggage","text":"The express company is auctioning unclaimed baggage. Bidders are buying sealed trunks on hope and coming away with a lot of hats.","base":12,"risk":5,"s":"You list the contents of the stranger trunks, including a stuffed owl and someone’s love letters, and three people claim the letters.","w":"Your version has a trunk containing a live Congressman; Washington denies it, which settles nothing."},
  {"id":"t37","name":"A foot race on C Street","text":"A foot race down C Street between a miner and a bartender drew two thousand spectators and four thousand dollars in bets.","base":16,"risk":9,"s":"You report the bartender won by a nose and the miner by a fist, and both sides say you were paid.","w":"In your account the two men ran clear to Gold Hill and back before anyone remembered to stop them; they are running still."},
  {"id":"t38","name":"The schoolhouse stove","text":"The schoolhouse stove has been smoking so badly the children are taught by ear. The school board has been asked for twelve dollars.","base":8,"risk":8,"s":"You suggest the board could be smoked out too, and the twelve dollars appear.","w":"Your report has a child graduating without ever having seen the teacher; the board buys two stoves."},
  {"id":"t39","name":"A dentist versus a barber","text":"The barber has started pulling teeth on the side, and the dentist has started giving shaves. The town is watching to see who blinks.","base":12,"risk":10,"s":"You report that the safest place in town is now the undertaker’s, and both men glare at you.","w":"You claim a customer had his beard pulled and his teeth shaved; both shops are full by noon."},
  {"id":"t40","name":"The widow’s fourth husband","text":"The Widow McCann has married for the fourth time, at the same church, with the same minister, wearing the same dress.","base":12,"risk":14,"s":"You note the minister now gives her a discount, and the widow sends round a frosty note and a slice of cake.","w":"Your report has the dress engaged to the minister; the widow calls at the office with an umbrella."},
  {"id":"t41","name":"A temperance lecturer arrives","text":"A temperance lecturer has booked the opera house for three nights. Several saloon keepers have bought front-row tickets to keep an eye on him.","base":13,"risk":11,"s":"You report that he was given a standing ovation by men who could not otherwise stand, and he writes to thank you.","w":"Your account has the lecturer converted by the saloon keepers on the third night; he opens a bar in Gold Hill."},
  {"id":"t42","name":"Hotel clerk’s memory","text":"The night clerk at the International can name every guest since 1860 and what each one owed. Several are anxious he will.","base":10,"risk":12,"s":"You print a few of the smaller debts as a public service, and several bills are settled that afternoon.","w":"You claim the clerk once named a man’s debts so fast the man paid twice; the clerk is offered a seat in the legislature."},
  {"id":"t43","name":"A runaway balloon","text":"A travelling aeronaut’s balloon broke loose from its moorings during the exhibition and drifted east with nobody in it but a chicken.","base":16,"risk":4,"s":"You report the chicken is the first fowl of the Territory to reach the Rocky Mountains, and the aeronaut wants it back.","w":"In your version the chicken lands in Salt Lake City and is made a bishop; the aeronaut sues for wages."},
  {"id":"t44","name":"The fire bell rings for nothing","text":"The fire bell rang for an hour last night because a goat got into the tower. Four companies turned out to fight the goat.","base":13,"risk":5,"s":"You describe the goat’s rescue in full military detail, and the goat is promoted to captain.","w":"Your account has the goat directing the hoses from the tower and refusing to come down until paid; it is still there."},
  {"id":"t45","name":"Restaurant oysters by express","text":"A C Street restaurant is serving fresh oysters brought over the Sierra by express. The oysters are expensive, and only somewhat fresh.","base":11,"risk":9,"s":"You describe the oysters as well-travelled, and the restaurant offers you one on the house, if you dare.","w":"Your report has an oyster arriving with its own passport and opinions; the restaurant sells out at double price.","pay":true},
  {"id":"t46","name":"A young lady from Philadelphia","text":"A young lady from Philadelphia has arrived to teach music and has received eleven proposals in her first week, two by letter.","base":14,"risk":12,"s":"You print the proposals by category, and four suitors want satisfaction.","w":"Your account has the proposals arriving by mule train; she marries the mule driver, and the town goes into mourning."},
  {"id":"t47","name":"The Zephyr and a roof","text":"The Zephyr lifted a tin roof off a Gold Hill saloon and flew it to Carson, where the owner found it and sent a bill for postage.","base":13,"risk":3,"s":"You report the roof made better time than the stage, and the stage company complains.","w":"Your piece has the roof landing on the Governor’s house and being kept as a new wing; the saloon is now open-air."},
  {"id":"t48","name":"The mysterious stranger with a cane","text":"A stranger with a gold-headed cane has been seen walking up and down C Street every day for a week, speaking to no one.","base":14,"risk":7,"s":"You publish six theories about him, from Russian prince to escaped bookkeeper, and he buys every copy.","w":"In your version he is revealed as the Emperor of Washoe, and is saluted in the street; he takes it very well."},
  {"id":"t49","name":"A Thanksgiving turkey shoot","text":"The militia held a turkey shoot and the turkeys came out well ahead. Only two were hit, both by accident.","base":11,"risk":6,"s":"You print the score as Turkeys 48, Militia 2, and the militia drills harder.","w":"Your account has the turkeys forming their own company and marching on Carson; the Governor declares a holiday."},
  {"id":"t50","name":"The big boot sign","text":"The bootmaker’s giant wooden boot, eight feet tall, has been stolen. He offers a reward and says it was too big to hide.","base":10,"risk":4,"s":"You suggest searching the feet of the tallest men in town, and three of them are stopped by a deputy.","w":"You claim the boot was seen walking toward Gold Hill on its own; the bootmaker sells walking boots for a month."},
  {"id":"t51","name":"A practical joke at the hotel","text":"Somebody painted the International Hotel’s mule green for St. Patrick’s Day. The mule has taken it badly.","base":12,"risk":6,"s":"You report the mule’s complaint in its own words, and the culprits confess to keep the credit.","w":"In your version the mule is marching in the parade and leading it; the Irish societies adopt it as a mascot."},
  {"id":"t52","name":"A hurdy-gurdy house opens","text":"A new dance hall on D Street charges fifty cents a dance and has hired a fiddler who plays faster when tipped.","base":13,"risk":14,"s":"You report that the fiddler’s top speed has not yet been reached, and the churches write in about your research.","w":"Your piece has a miner tipping so heavily the fiddler played clean through to Thursday; the ministers preach about you by name."},
  {"id":"t53","name":"An undertaker’s advertising","text":"The undertaker has begun advertising a spring sale. The town is unsure whether to be offended or to take advantage.","base":11,"risk":10,"s":"You review the sale as a bargain for the far-sighted, and the undertaker sends you a cheerful thank-you and a tape measure.","w":"Your report has men queueing to be buried early to save money; the undertaker extends the sale.","pay":true},
  {"id":"t54","name":"The parrot at the Sazerac","text":"The Sazerac saloon’s parrot has learned to call for drinks in the bartender’s voice. The bartender has served it eleven times.","base":14,"risk":5,"s":"You call the parrot the best customer in the house and the only one who pays in conversation.","w":"You report the parrot ran up a tab of forty dollars and skipped for Sacramento; the bartender files a complaint with the sheriff."},
  {"id":"t55","name":"A boarding-house fire drill","text":"A Gold Hill landlady has introduced fire drills at two in the morning. Her boarders have introduced a petition at three.","base":9,"risk":7,"s":"You praise her foresight and describe her boarders’ nightshirts, and nobody speaks to you at breakfast.","w":"Your account has the boarders practising so well they evacuated before the landlady rang the bell, and kept going to Carson."},
  {"id":"p01","name":"The legislature names a county","text":"The legislature has spent three days choosing a name for the new county. Nineteen names have been proposed, eleven rejected, and two members are no longer speaking.","base":10,"risk":10,"s":"You report that the county was nearly named after a member’s mule, and the member writes to say it was a horse.","w":"You announce the county will be called “Unanimous”, and the legislature, too tired to object, nearly adopts it."},
  {"id":"p02","name":"A toll road for the toll road","text":"A franchise holder wants to charge a toll on the only road leading to his other toll road. Teamsters are gathering at the bridge with opinions and axe handles.","base":13,"risk":14,"pay":true,"s":"You estimate that a wagon of flour now pays more in tolls than flour, and the teamsters buy every copy.","w":"You report he has applied to toll the air above the road, and three people ask where to pay."},
  {"id":"p03","name":"Orion’s inkstand budget","text":"The Secretary’s office has asked Washington to pay for stationery. Washington has written back asking what an inkstand is and why the Territory needs four.","base":9,"risk":4,"s":"Your account of Orion defending each inkstand by name is gentle, and Orion pretends not to have read it.","w":"You claim the Territory has ordered a solid silver inkstand the size of a stagecoach; Washington writes again."},
  {"id":"p04","name":"The statehood question","text":"Half the Territory wants statehood at once, the other half wants to know who pays for it. Both halves hold a meeting on the same night, in the same hall.","base":14,"risk":15,"s":"You describe the two meetings sharing one lamp and one chairman, and both halves claim the article supports them.","w":"You report Nevada was admitted as a state by telegraph and then rejected by the next telegraph; the saloons hold two celebrations."},
  {"id":"p05","name":"The constitutional convention","text":"Delegates have assembled in Carson to write a state constitution. The first day was spent on the question of whether to open with a prayer, a toast, or both.","base":12,"risk":13,"s":"You report the convention has adopted a preamble, three amendments to the preamble, and a resolution to adjourn for lunch.","w":"Your version has the delegates write a clause forbidding the Washoe Zephyr; several voters think it is the best part."},
  {"id":"p06","name":"The mining tax","text":"The legislature proposes to tax the mines on their output. The mines report that, by remarkable coincidence, none of them has any output this year.","base":15,"risk":18,"pay":true,"s":"You print a list of mines declaring losses beside the size of their owners’ new houses; the owners stop sending feet.","w":"You report a mine that declared negative ore, owing the Territory a hole, and it is reprinted in San Francisco."},
  {"id":"p07","name":"County seat stolen","text":"Two towns both claim to be the county seat. Last night the county records were carried off in a wagon by persons from one of them, and the other wants them back.","base":16,"risk":14,"s":"You follow the wagon’s trail and describe it as a siege, and both towns accuse you of taking the other’s side.","w":"You report the courthouse itself was stolen, on rollers, and a farmer swears he saw it pass."},
  {"id":"p08","name":"The jury that wouldn’t","text":"A jury in a horse-theft case has been out for four days. The bailiff reports they are deadlocked on the facts, the law, and whose turn it is to fetch water.","base":12,"risk":8,"s":"You print the bailiff’s account of the jury’s card game, and the judge sends for the cards.","w":"You report the jury has acquitted the horse and convicted the defendant’s hat; the court reporter frames it."},
  {"id":"p09","name":"A lawsuit over a landslide","text":"A landslide carried one man’s ranch down the mountain and set it on top of his neighbour’s. Both men claim the ranch, and the case comes up Tuesday.","base":15,"risk":7,"s":"You report the arguments of both lawyers in full, and readers bet on the verdict in every saloon.","w":"Your account has the judge rule that the upper ranch owns the lower ranch’s cellar; lawyers argue about it for a month."},
  {"id":"p10","name":"The sheriff’s new star","text":"The sheriff has ordered a new badge from San Francisco, and it is larger than anyone expected. He says it is regulation. It is the size of a pie plate.","base":9,"risk":9,"s":"You describe the badge reflecting the sun into the eyes of evildoers, and the sheriff is half flattered.","w":"You report the sheriff now uses the badge as a shield and a frying pan; he comes round to discuss it."},
  {"id":"p11","name":"Jailbreak with a spoon","text":"Two prisoners left the county jail overnight through a hole in the wall. The deputy says they used a spoon. The wall says it was mostly mud.","base":13,"risk":10,"s":"You praise the prisoners’ industry and recommend them for the road crew, and the deputy cancels your subscription.","w":"You report they dug with a teaspoon and left a thank-you note about the soup; the county demands a stronger wall and better soup."},
  {"id":"p12","name":"Union meeting, secesh heckler","text":"A Union mass meeting on C Street was interrupted by a man shouting for Jeff Davis from a balcony. He has since apologised, and says he was shouting at a dog named Jeff.","base":14,"risk":16,"s":"You print his explanation with a straight face and a description of the dog, and both parties write letters.","w":"You report the dog has been arrested for disloyalty and released on bond; the dog’s owner is not amused."},
  {"id":"p13","name":"The flour sack auction","text":"A sack of flour is being auctioned for the Sanitary Fund, bought, donated back, and auctioned again. It has raised several thousand dollars and never been baked.","base":18,"risk":6,"s":"You follow the sack from town to town and call it the most valuable flour on earth; donations rise.","w":"You report the sack has been elected to the legislature and is the hardest-working member; the legislature does not laugh."},
  {"id":"p14","name":"The rival editor’s spelling","text":"Mr. Boggs of the Gold Hill Clarion has printed that the Enterprise cannot spell “Washoe”. He spells it three ways in the same paragraph.","base":16,"risk":19,"s":"You reprint his paragraph with each spelling numbered, and he replies in a column you have to admit is longer.","w":"You publish a dictionary of Boggs’s spellings; he sends a friend round with a formal note and a pistol case."},
  {"id":"p15","name":"The mail is late again","text":"The overland mail is eleven days late. The postmaster blames snow, the stage company blames the postmaster, and the snow has not commented.","base":11,"risk":6,"s":"You print an interview with the snow, and the postmaster threatens to stop delivering the Enterprise.","w":"You report the mail was eaten by a bear who has learned to read and refuses to give up the Atlantic Monthly."},
  {"id":"p16","name":"The telegraph wire is down","text":"The telegraph line to California has been down three days. Some say a tree fell on it. Some say a mine superintendent cut it to delay bad news about his stock.","base":15,"risk":18,"pay":true,"s":"You note that the stock rose every day the wire was down, and the superintendent stops speaking to you.","w":"You report the line was cut by a woodpecker in the pay of a broker; the broker issues a denial, which makes it worse."},
  {"id":"p17","name":"A duel postponed for rain","text":"Two gentlemen arranged to meet at dawn with pistols. It rained, and both sent word they would not stand in the mud for anybody’s honour.","base":13,"risk":14,"s":"You report the exchange of notes about the weather in full, and both gentlemen feel misunderstood.","w":"You report they settled it by umbrella at ten paces; both send seconds to see you instead."},
  {"id":"p18","name":"Legislators’ per diem","text":"Members of the legislature are paid by the day. The session, which was to last forty days, is now in its sixty-third and shows no sign of finishing anything.","base":14,"risk":17,"s":"You calculate the cost per law passed and print it in a box; the members vote to censure the box.","w":"You report a bill to extend the session until every member has paid off his boarding house; it nearly passes."},
  {"id":"p19","name":"The Speaker’s gavel","text":"The Speaker broke his gavel calling the House to order and has been using a pick handle. Order has improved remarkably.","base":10,"risk":9,"s":"You recommend the pick handle to every assembly in the Union, and the Speaker keeps the clipping.","w":"You report he now calls the House to order with a quartz drill and a charge of powder; members sit at the back."},
  {"id":"p20","name":"A sheriff’s election","text":"Three men are running for sheriff. One promises order, one promises economy, and one promises to buy drinks, and he is well ahead.","base":14,"risk":12,"s":"You describe the campaign as a contest between virtue and whiskey, and the whiskey candidate thanks you.","w":"You report a fourth candidate, a mule, polling strongly in the outer wards; it gets nine votes."},
  {"id":"p21","name":"Orion and the Territorial seal","text":"The Territorial seal has gone missing from the Secretary’s office. Orion has searched every drawer twice and suspects it is in the drawer he searched first.","base":10,"risk":3,"s":"You report the hunt kindly and the seal turns up in a boot; Orion sends you a cake.","w":"You report the seal was used to crack walnuts at a dinner party; Orion writes to you as your brother, more in sorrow."},
  {"id":"p22","name":"The Governor’s reception","text":"The Governor has held a reception at which the punch ran out in twenty minutes and the speeches did not run out at all.","base":12,"risk":11,"s":"You give the punch a warmer review than the speeches, and the speakers notice.","w":"You report the speeches were so long the punch bowl was refilled by rain; the Governor’s staff stop inviting you."},
  {"id":"p23","name":"Claim jumping in court","text":"A claim-jumping suit has turned on whether a stake was pulled up by a man or a cow. Both parties have produced witnesses, and the cow has been subpoenaed.","base":16,"risk":8,"s":"You describe the cow’s appearance in court with great dignity, and the judge has to call a recess.","w":"You report the cow testified for the plaintiff and was cross-examined for an hour; the defendant appeals."},
  {"id":"p24","name":"The justice of the peace","text":"The new justice of the peace holds court in his saloon and fines every offender a round for the house. Justice has never been more popular.","base":15,"risk":12,"s":"You praise his system as self-financing, and the temperance society writes in with heat.","w":"You report he now sentences repeat offenders to tend bar; the crime rate rises sharply."},
  {"id":"p25","name":"A poll tax rebellion","text":"Miners in one district are refusing to pay the poll tax, on the grounds that nobody has ever polled them about anything.","base":13,"risk":15,"s":"You endorse polling them first and taxing them afterward, and the assessor arrives with a ledger.","w":"You report the miners have seceded and declared the Republic of Six-Mile Canyon; three of them start drafting a flag."},
  {"id":"p26","name":"The capital fight","text":"Virginia City wants the capital moved from Carson. Carson says Virginia City can’t even keep its roofs on.","base":17,"risk":16,"s":"You side loyally with Virginia City and sneer at Carson’s weather, and Carson stops selling the Enterprise.","w":"You report Virginia City will simply take the capitol building on a freight wagon; Carson posts guards."},
  {"id":"p27","name":"A secessionist flag on a mine","text":"Somebody ran up a Confederate flag over a mine hoist during the night. The miners took it down, and are now arguing about who gets to keep it.","base":14,"risk":18,"s":"You report the culprit was probably homesick and certainly a bad seamstress; both sides grumble.","w":"You report the flag was raised by the mine’s mule as a protest over its pay; the mule’s owner denies everything."},
  {"id":"p28","name":"The provost marshal visits","text":"An army officer has arrived to ask about disloyal talk in the saloons. The saloons have become remarkably quiet and very patriotic.","base":12,"risk":17,"s":"You describe saloons full of men toasting the Union in whispers, and the officer asks who told you.","w":"You report a bartender sold forty Union flags in an hour and then ran out of cloth and started on tablecloths; he gets eleven orders."},
  {"id":"p29","name":"A frontier lawyer’s speech","text":"A defence lawyer spoke for six hours on a case involving a stolen saddle. He quoted Cicero, the Bible and a song about a whale.","base":11,"risk":8,"s":"You summarise the speech in one sentence and the lawyer threatens to sue for brevity.","w":"You report the jury acquitted the client only to make him stop; the lawyer uses your piece as an advertisement."},
  {"id":"p30","name":"The tax assessor’s mule","text":"The county assessor was thrown from his mule on his rounds and has been assessing from the ground for two days.","base":9,"risk":7,"s":"You report that his valuations have dropped noticeably since he lost the high view; property owners are delighted.","w":"You report the mule is now doing the assessments and is fairer; the assessor demands a retraction and a new mule."},
  {"id":"p31","name":"Licences for everything","text":"The legislature has passed a licence fee for saloons, peddlers, theatres, billiard tables, lotteries and, apparently by mistake, preachers.","base":15,"risk":14,"s":"You publish a list of things not yet licensed, and the legislature takes it as a to-do list.","w":"You report a licence fee for whistling on Sundays; a deputy tries to collect it."},
  {"id":"p32","name":"The Union Party convention","text":"The Union Party met to choose its candidates. Seven men wanted to run for Congress, and the convention resolved the matter by nominating none of them.","base":13,"risk":15,"s":"You describe all seven nursing their disappointment at the same bar, and all seven correct your spelling of their names.","w":"You report they nominated a portrait of George Washington as the only man everyone trusted; a few delegates think it a good idea."},
  {"id":"p33","name":"An Indian agent’s report","text":"The Indian agent has returned from Pyramid Lake with a report that the Paiute bands kept every promise and the government kept almost none of its own.","base":10,"risk":12,"s":"You print the agent’s figures plainly beside the government’s, and Washington is not pleased with either of you.","w":"You exaggerate the government’s blunders until the agent asks you to tone it down; it was bad enough as it was."},
  {"id":"p34","name":"Fort Churchill’s new cannon","text":"Fort Churchill has received a new cannon and fired it in salute. Windows broke in a ranch house four miles off.","base":12,"risk":8,"s":"You report the rancher has presented the army a bill, with interest and a drawing of the window.","w":"You report the cannonball is still travelling and was last seen over Utah; the commanding officer sends a stiff note."},
  {"id":"p35","name":"A recount by lamplight","text":"The election in one precinct is being recounted because there are more ballots than voters. Officials say several citizens were very enthusiastic.","base":16,"risk":18,"s":"You commend the precinct’s civic spirit and estimate how many times each voter voted; the officials stop smiling.","w":"You report a ballot was cast by a man buried in 1859, in a firm hand; the cemetery committee investigates."},
  {"id":"p36","name":"Fist fight in the Council","text":"Two members of the Territorial Council came to blows over a bridge franchise. Neither was hurt, but the bridge bill was badly torn.","base":17,"risk":18,"s":"You report the fight round by round and award it on points, and the loser wants a rematch with you.","w":"You report the members fought to a draw and then voted the bridge to each other; both send their seconds."},
  {"id":"p37","name":"The new jail is too comfortable","text":"Citizens complain that the new county jail has stoves, blankets and three meals a day, and several tramps are committing crimes to get in.","base":13,"risk":7,"s":"You review the jail like a hotel and give it four stars; the sheriff starts a waiting list.","w":"You report a prisoner refused to be released until the end of winter; the county wants to charge rent."},
  {"id":"p38","name":"Orion’s spelling of Esmeralda","text":"An official document from the Secretary’s office has spelled Esmeralda County four different ways. Orion says the county is spelled differently in different weather.","base":9,"risk":4,"s":"You defend Orion handsomely, and point out that the county itself can’t decide where its border is either.","w":"You report Esmeralda has asked to be renamed something Orion can spell; he is more amused than you expected."},
  {"id":"p39","name":"A boundary war with California","text":"California and Nevada both claim the town of Aurora. It has held elections for both, and has two sets of officials who meet in the same building.","base":18,"risk":13,"s":"You describe two county clerks sharing one inkwell in silence, and both legislatures take it personally.","w":"You report Aurora has decided to be in Oregon to save trouble; Oregon does not reply."},
  {"id":"p40","name":"Rival paper’s fake telegram","text":"The Virginia Union printed a telegram announcing a great battle. The battle turned out to be a fight between two printers over a type case.","base":15,"risk":16,"s":"You print a correction for them, very helpfully, with a map of the type case.","w":"You report the Union’s next telegram will announce the end of the world; their editor calls on you with a horsewhip."},
  {"id":"p41","name":"A lawsuit over a goat","text":"A boarding-house keeper is suing her neighbour’s goat, or rather its owner, for eating a dress off the line. The goat appeared in court wearing part of it.","base":14,"risk":5,"s":"You describe the goat’s courtroom manners with admiration, and the goat’s owner buys twenty copies.","w":"You report the goat was found guilty and sentenced to a bonnet; the plaintiff thinks it’s hilarious and the goat does not."},
  {"id":"p42","name":"The Territorial printer’s bill","text":"The Territorial printer has billed the legislature for printing its laws. The bill is longer than the laws.","base":11,"risk":14,"pay":true,"s":"You compare the bill to the laws page by page, and the printer withdraws your discount.","w":"You report the printer charges extra for the commas and double for the long words; he denies the double."},
  {"id":"p43","name":"A militia company forms","text":"A new militia company is drilling in the street. It has fine uniforms, a band and a flag. It has not yet got guns.","base":12,"risk":9,"s":"You praise the uniforms and the band, and note the enemy will be very impressed until it arrives.","w":"You report the company has captured a heavily defended saloon in good order; the captain asks for a correction."},
  {"id":"p44","name":"The Senate chaplain","text":"The legislature’s chaplain has asked to be paid in advance, since he prays for them every morning and sees no improvement.","base":13,"risk":10,"s":"You side with the chaplain, saying his task is the hardest in the Territory; members grumble.","w":"You report the chaplain has given up praying for the legislature and is now praying for the Territory instead; the members are offended."},
  {"id":"p45","name":"Survey of the Comstock lode","text":"A government surveyor has been sent to map the Comstock lode. Every mine owner has offered him dinner and a different map.","base":14,"risk":16,"s":"You publish an imaginary map combining all the owners’ maps; the lode goes in nine directions at once.","w":"You report the surveyor found that the lode runs under the Governor’s house; the Governor sends for a shovel."},
  {"id":"p46","name":"Habeas corpus for a horse","text":"A lawyer has filed a writ of habeas corpus on behalf of a horse being held by a livery stable for unpaid feed.","base":13,"risk":6,"s":"You report the arguments respectfully, and the horse’s case turns into a matter of principle across town.","w":"You report the horse has been released on its own recognisance and returned to give testimony; the judge objects to your coverage."},
  {"id":"p47","name":"A bill to abolish the Zephyr","text":"A member from Carson has introduced a bill to fine anyone found responsible for the Washoe Zephyr. It has passed a first reading.","base":12,"risk":7,"s":"You report the debate and estimate who the Zephyr would vote for; the member is not amused.","w":"You report the Zephyr has blown the bill out of the legislature and into Utah; several members believe you."},
  {"id":"p48","name":"A constable resigns","text":"A constable has resigned after six weeks, saying the job was mostly carrying drunks home and he has run out of back.","base":10,"risk":5,"s":"You print his letter of resignation with a few improvements, and he buys you a drink.","w":"You report the drunks have held a meeting and asked him to reconsider; he does, briefly."},
  {"id":"p49","name":"Who owns the water?","text":"A ranchman and a mill owner both claim the same creek. The ranchman has dammed it, and the mill owner has dammed it back.","base":14,"risk":14,"s":"You report the war of the dams in military terms; both sides use your article as a plan.","w":"You report the creek has filed a complaint against both men and gone underground; the miners nearby claim it."},
  {"id":"p50","name":"A judge on horseback","text":"The circuit judge holds court wherever he happens to be when a case comes up, which yesterday was the middle of a river crossing.","base":13,"risk":8,"s":"You describe his rulings as wet but sound, and the judge sends a genial note.","w":"You report the judge sentenced a man to a fine and a horse paid it; the judge sends a less genial note."},
  {"id":"p51","name":"The Secretary’s office stove","text":"The stove in the Secretary’s office smokes so badly that clerks work in shifts. Orion has asked Washington for a new one and been told to open a window.","base":9,"risk":3,"s":"You report the clerks have developed lungs like blacksmiths’ bellows; Orion laughs.","w":"You report the smoke signals from the office have been mistaken for an alarm by three towns; Washington sends a smaller stove."},
  {"id":"p52","name":"A trial for bad singing","text":"A man was arrested for disturbing the peace by singing outside a boarding house at two in the morning. He insists he was serenading and demands a jury of musical persons.","base":13,"risk":6,"s":"You report the jury’s deliberations as a concert review; he is convicted on pitch alone.","w":"You report the jury acquitted him on the condition that he never sing again, and one juror wept; the singer writes in to correct the verse."},
  {"id":"p53","name":"Draft rumours in Washoe","text":"A rumour has gone round that the government will draft Washoe men for the war. Several men have discovered urgent business in California.","base":15,"risk":15,"s":"You report the sudden rush of travellers westward as a great boom in tourism; the provost marshal wants their names.","w":"You report the draft will take only men who can spell; half the Territory is safe, and Mr. Boggs is safest of all."},
  {"id":"p54","name":"The election bet","text":"Two men have bet on the governorship race. The loser must wheel the winner down C Street in a barrow. Both have hired training barrows.","base":16,"risk":7,"s":"You publish the barrow route and the expected crowd, and the town turns out in thousands.","w":"You report the loser has been training a horse to push the barrow; the winner calls it cheating and wants you to judge."},
  {"id":"p55","name":"The legislature adjourns","text":"The legislature has finally adjourned after passing four hundred bills. Nobody, including the members, knows what is in most of them.","base":15,"risk":16,"s":"You summarise all four hundred bills in a single column, and three members are surprised by what they voted for.","w":"You report one bill made it illegal to be from Carson on Tuesdays; a lawyer files suit to enforce it."},
  {"id":"h01","name":"A sea serpent in Lake Tahoe","text":"Two fishermen swear something forty feet long and very rude surfaced beside their boat at dusk, looked them over, and went back down unimpressed.","base":20,"risk":8,"s":"In your version it is sixty feet long and takes one of the oars, and three more fishermen remember seeing it.","w":"Your serpent wears a stovepipe hat and asks for the Carson road; a San Francisco paper sends a reporter up with a harpoon."},
  {"id":"h02","name":"Mono Lake does the washing","text":"A teamster claims he left his shirts tied to a rope in Mono Lake overnight and the alkali water scoured them whiter than any laundry in the Territory.","base":14,"risk":4,"s":"You add that it also took the buttons, the collar, and most of the shirt.","w":"You report that a man bathed in it and came out so clean his own dog failed to recognise him and had him arrested.","pay":true},
  {"id":"h03","name":"The camel caravan","text":"A train of camels, left over from some army experiment, has turned up on the Carson trail. The mule teams bolt at the sight of them and the camels look down on everyone.","base":17,"risk":7,"s":"You describe the camel’s opinion of the mules at length, in the camel’s own words.","w":"In your account a camel wins a seat in the legislature on a temperance ticket, being the only member who can go a week without a drink."},
  {"id":"h04","name":"Giant sagebrush near Dayton","text":"A rancher reports a sagebrush bush so large that a family of five has been living under it since spring and paying no rent.","base":13,"risk":5,"s":"You give the bush a front porch and a mortgage.","w":"You report the bush has been incorporated as a town, elected a mayor, and applied to be the territorial capital."},
  {"id":"h05","name":"A jackass rabbit outruns the telegraph","text":"A Pony Express rider claims a jackass rabbit kept pace with him for twenty miles, then overtook him out of what looked like pure spite.","base":15,"risk":3,"s":"You clock the rabbit at a speed that would shame a locomotive.","w":"You report the rabbit delivered the mail itself and the company is considering putting him on salary."},
  {"id":"h06","name":"The coyote at the boarding house","text":"A coyote has taken to sleeping on the porch of a C Street boarding house, and the landlady says he pays more regularly than half her lodgers.","base":12,"risk":4,"s":"You describe him coming down to breakfast and complaining about the coffee.","w":"Your coyote is elected president of the lodgers’ association and demands a reduction in rent for all."},
  {"id":"h07","name":"Snow in July","text":"It snowed for ten minutes on the Fourth of July, in the middle of the parade, on the band, and the band played on.","base":14,"risk":3,"s":"You add a sleigh to the parade and a brass band frozen solid in mid-note.","w":"The notes, you report, thawed out in August and played themselves all over town for a week."},
  {"id":"h08","name":"The talking spirit of Six-Mile Canyon","text":"A visiting spiritualist, Madame Velours, holds a séance at the International Hotel. The table rises, the lamps dim, and a ghost asks for a drink.","base":18,"risk":12,"s":"You report the ghost also asked for a loan and a stock tip.","w":"In your account the ghost gives a tip on a wildcat mine, the stock jumps, and Madame Velours leaves town with the proceeds before the ledge does."},
  {"id":"h09","name":"A phrenologist reads the town","text":"Professor Ezra Bumpley, phrenologist, is feeling the heads of Virginia City for a dollar apiece and finding genius in every one of them.","base":13,"risk":9,"s":"You have him find an organ of mining speculation the size of a hen’s egg on every head in town.","w":"You report the Professor felt the head of the town’s leading banker and fled on the evening stage without his fee."},
  {"id":"h10","name":"Dr. Pettibone’s Elixir","text":"A patent-medicine man is selling an elixir from the back of a wagon that he says cures dyspepsia, baldness, bad luck and the silver fever.","base":14,"risk":10,"pay":true,"s":"Your write-up has the elixir curing a man of his mother-in-law.","w":"You report a bottle was poured on a dead mine and it began producing again, and the doctor’s wagon is besieged by stockholders."},
  {"id":"h11","name":"The balloon ascension","text":"An aeronaut, Captain Fogg, has promised to go up in a silk balloon from the plaza on Sunday. The Zephyr has been invited too, without anyone asking it.","base":19,"risk":8,"s":"You have the balloon go up, come down, go up again and finally settle on the Ophir hoisting works.","w":"In your version the Zephyr carries Captain Fogg to Salt Lake City, where he is received with great courtesy and a bill for the damages."},
  {"id":"h12","name":"A perpetual-motion machine","text":"A Gold Hill inventor has built a machine of wheels and weights that he says will run forever. So far it has run since Tuesday, with help.","base":12,"risk":6,"s":"You report that it ran so long it wore out the inventor.","w":"Your machine runs backward by mistake, unwinding the week, and the inventor has to pay his board for Tuesday twice."},
  {"id":"h13","name":"The mesmerist’s subject","text":"A travelling mesmerist put a miner into a trance on the stage of Maguire’s Opera House and cannot, as of press time, get him out of it.","base":17,"risk":9,"s":"You describe the miner still asleep and still sitting at the edge of the stage, collecting tips.","w":"You report that the miner, in his trance, located a rich ledge, and every speculator in town is now trying to get himself mesmerised."},
  {"id":"h14","name":"The menagerie comes to town","text":"A circus with a lion, a dancing bear and an elephant has arrived over the Sierra. The elephant is the first ever seen on the Comstock, and is not pleased about it.","base":18,"risk":6,"s":"You describe the elephant inspecting C Street and finding it wanting.","w":"In your report the elephant falls down a mine shaft and is hoisted out at the next level with a bucket of ore in his trunk."},
  {"id":"h15","name":"The ghost of the Gould & Curry","text":"Night-shift miners say a lantern moves through an abandoned drift on the 400-foot level, and nobody holding it.","base":19,"risk":10,"s":"You give the ghost a name, a grudge and a pick.","w":"You report the ghost is a former shift boss still docking men’s pay; the miners threaten to strike unless he is exorcised."},
  {"id":"h16","name":"A child prodigy of figures","text":"A boy of nine in Silver City can multiply any two numbers in his head faster than a bank clerk with a pencil.","base":11,"risk":3,"s":"You have him multiply the national debt by the number of saloons on C Street, and get the same answer twice.","w":"You report that the stock brokers have hired him and he has already gone bankrupt twice and recovered both times before lunch."},
  {"id":"h17","name":"The comet","text":"A comet with a long pale tail hangs over Mount Davidson each night. Half the town says it means war, the other half says it means a strike.","base":15,"risk":4,"s":"You report the comet slowing to look at the town.","w":"You report a fragment of the comet landed in a claim on Cedar Hill and assayed at three thousand dollars a ton."},
  {"id":"h18","name":"The eclipse","text":"The sun went partly out for an hour on Wednesday. Mules sat down, chickens went to bed, and a gambler on B Street tried to cash in before the end of the world.","base":14,"risk":3,"s":"You describe the chickens’ embarrassment the next morning.","w":"In your version the sun goes out entirely and the gas company sends it a bill."},
  {"id":"h19","name":"The teamster’s mirage","text":"A teamster crossing the Forty-Mile Desert says he saw a lake, a steamboat and a band concert, and drove three hours toward them.","base":13,"risk":3,"s":"You have him hear the band play and the steamboat whistle.","w":"You report the mirage was so good he bought a ticket on the steamboat, and is now suing it."},
  {"id":"h20","name":"The hot spring that cooks","text":"At Steamboat Springs the water comes up boiling. A traveller cooked an egg in it and is now trying to cook his whole dinner.","base":12,"risk":3,"s":"You report a hotel there that boils its guests’ coffee and boots in the same pool.","w":"You report a man fell in and came out perfectly cooked and very angry, and the town claims he was undercooked."},
  {"id":"h21","name":"A cave of crystals","text":"Prospectors broke into a cave near Washoe Lake lined with crystals that glitter by lantern-light like a cathedral of ice.","base":16,"risk":6,"s":"Your cave has an echo that repeats a man’s words with corrections.","w":"You report the crystals are pure diamond and half the town rushes out to the cave and comes back with quartz."},
  {"id":"h22","name":"The Pony rider and the blizzard","text":"A Pony Express rider came in four hours late, frozen, with a story about riding over a mountain that was not there the last time he passed.","base":15,"risk":4,"s":"You give the mountain a name and the rider a medal.","w":"You report the mountain followed him into town and is now standing behind the stables."},
  {"id":"h23","name":"Bones of a monster","text":"A placer miner on the Carson River has dug up a thigh bone longer than a man, and wants to know what it belonged to before he charges admission.","base":18,"risk":8,"s":"You reconstruct the beast as a lizard the size of a stagecoach.","w":"In your version he finds the whole creature, harnesses it, and uses it to haul ore."},
  {"id":"h24","name":"The singing mule","text":"A pack mule at a Gold Hill corral brays in tune. Its owner says it has a repertoire of three hymns and one song unfit for print.","base":13,"risk":5,"s":"You review the mule’s performance as a concert.","w":"You report the mule has been engaged at Maguire’s Opera House, and the leading soprano has resigned in protest."},
  {"id":"h25","name":"A rain of frogs","text":"After a cloudburst, the streets of Dayton were covered with tiny frogs. Nobody knows where they came from. The frogs are not talking.","base":14,"risk":3,"s":"You have the frogs hold a public meeting about it.","w":"You report the frogs voted to annex Dayton, and the town council has agreed to negotiate."},
  {"id":"h26","name":"The man who never sleeps","text":"A miner on the Chollar claims he has not slept a wink in eleven years, and has the eleven years of savings from extra shifts to prove it.","base":12,"risk":4,"s":"You report he spent the extra hours learning to whistle in Latin.","w":"You report a physician set up a cot beside him to watch, and fell asleep in eleven minutes."},
  {"id":"h27","name":"The lady lecturer on temperance","text":"Mrs. Abigail Thorne is lecturing at the Opera House on the evils of drink. She is very eloquent. Attendance at the saloons has gone up in self-defence.","base":13,"risk":11,"s":"You report she converted three bartenders and one barrel.","w":"In your account she storms a saloon with an axe, and the saloonkeeper sells tickets to watch."},
  {"id":"h28","name":"A meteor at Steamboat","text":"Something blazing fell out of the sky on Tuesday night near Steamboat Springs. Three ranchers saw it land; none of them will agree on where.","base":16,"risk":5,"s":"You report it is still too hot to touch and hissing like a kettle.","w":"You report the meteor is solid silver and has been claimed by four companies and a Methodist minister."},
  {"id":"h29","name":"The fortune-telling hen","text":"A Carson City widow owns a hen that pecks out answers from a board of letters. It predicted the last election, roughly.","base":14,"risk":6,"s":"You describe the hen being consulted by stock brokers.","w":"In your report the hen predicts a crash on the Comstock and the market panics, and the hen is arrested for fraud."},
  {"id":"h30","name":"The fastest stage driver in Washoe","text":"A stage driver says he made the run from Carson to Virginia in thirty-one minutes, and the horses are still talking about it.","base":12,"risk":4,"s":"You report the passengers arrived before they left.","w":"You report the coach arrived so fast the passengers had to wait a day for their own shadows to catch up."},
  {"id":"h31","name":"Tunnelling to China","text":"A Gold Hill man is digging a shaft straight down in his backyard. He says he is going to China, and he has only three thousand miles left.","base":13,"risk":5,"s":"You report he has already heard voices from below asking him to keep the noise down.","w":"You report he broke through into a tea house, ordered a cup, and came home in time for supper."},
  {"id":"h32","name":"The haunted piano","text":"A piano in an empty house on A Street plays at midnight, always the same waltz, always a little badly.","base":16,"risk":6,"s":"You report the ghost is taking requests.","w":"You report the town’s music teacher went in to give the ghost lessons and the ghost refused to pay."},
  {"id":"h33","name":"The cat that fell 300 feet","text":"A cat fell down the shaft of the Savage mine, 300 feet, and walked out of the cage at the bottom washing itself.","base":14,"risk":2,"s":"You say she landed on her feet and complained about the service.","w":"You report the cat has been employed by the company to inspect shafts and has demanded a union."},
  {"id":"h34","name":"The amazing memory man","text":"Signor Cordini, the Memory Man, can repeat any page of print after reading it once. He is performing at the Opera House this week.","base":12,"risk":7,"s":"You have him memorise the Enterprise and point out its mistakes.","w":"You report he memorised the books of a mining company and was run out of town by the directors."},
  {"id":"h35","name":"The dog that delivers newspapers","text":"A shaggy dog on D Street picks up the Enterprise each morning and delivers it to a list of houses known only to him.","base":11,"risk":2,"s":"You have him collect for subscriptions too.","w":"You report he has started his own paper and is outselling the Union."},
  {"id":"h36","name":"The whirlwind that took a cabin","text":"A whirlwind lifted a miner’s cabin off its foundations at Devil’s Gate and set it down a hundred yards away, with the miner still asleep inside.","base":16,"risk":4,"s":"You report he woke up and paid rent to a new landlord.","w":"You report the whirlwind returned the next day and took the cabin back, because the miner had not paid it."},
  {"id":"h37","name":"The fish that walks","text":"A fisherman at Pyramid Lake claims he caught a fish with legs, and that it walked home before he could show anyone.","base":15,"risk":5,"s":"You report the fish was seen buying tobacco in Reno.","w":"You report the fish has filed a mining claim and the fisherman is contesting it in court."},
  {"id":"h38","name":"The invisible ink banker","text":"A traveller is selling a patent ink that disappears after a week. He says it is ideal for love letters and contracts with the government.","base":12,"risk":13,"s":"You suggest the legislature has already ordered a barrel.","w":"You report the territorial budget was written in it and nobody can now find out where the money went."},
  {"id":"h39","name":"An Indian summer in December","text":"It is seventy degrees in December, the roses on B Street are blooming, and the oldest inhabitant says he has never seen the like, which he says every year.","base":10,"risk":2,"s":"You interview the oldest inhabitant, who remembers the weather of the Ice Age.","w":"You report the oldest inhabitant was born at the age of eighty, and has been young ever since."},
  {"id":"h40","name":"The Zephyr’s lost goat","text":"After yesterday’s Zephyr, a goat was found on the roof of the courthouse, eating the shingles. Its owner lives in Carson.","base":13,"risk":3,"s":"You have the goat testify in a case being heard below.","w":"You report the goat has been appointed a justice of the peace, being the only one on the roof when the vacancy opened."},
  {"id":"h41","name":"The talking telegraph","text":"An operator at the telegraph office swears the wire has begun to tap out messages nobody sent, all in a polite, ghostly hand.","base":16,"risk":7,"s":"You report the wire asked for a raise.","w":"You report the ghost is sending stock quotations from the next world, and they have so far been correct."},
  {"id":"h42","name":"A wild man of the Sierra","text":"Woodcutters near Lake Tahoe report a hairy, barefoot figure who steals their bacon and leaves the rind with a polite note.","base":18,"risk":6,"s":"You give him good manners and a handwriting fit for a bank.","w":"You report he was captured, shaved, put in a suit, and is running for Congress."},
  {"id":"h43","name":"The bottomless shaft","text":"An abandoned shaft on Cedar Hill is said to have no bottom. A miner dropped a rock in three days ago, and is still listening.","base":15,"risk":4,"s":"You report the rock hit bottom on Thursday and sent back a receipt.","w":"You report the rock came back up on Friday with a note complaining about the noise."},
  {"id":"h44","name":"Professor Hollow’s balloon of gas","text":"Professor Hollow is selling bottles of laughing gas at the Opera House. Volunteers inhale, laugh, and fall off the stage.","base":15,"risk":8,"s":"You describe the city council attending and agreeing on everything.","w":"You report the legislature took a dose and passed eleven laws in an hour, all of them funny."},
  {"id":"h45","name":"The poison spring","text":"A spring in the desert near Ragtown is said to kill anything that drinks from it. A teamster drank from it and is fine, but has lost his sense of humour.","base":13,"risk":4,"s":"You report the spring is bottling its water as a cure for optimism.","w":"You report the spring was sold to a stock company that is now trying to get investors to drink from it."},
  {"id":"h46","name":"The stagecoach robbed by bees","text":"A swarm of bees settled in the Carson stage, and the passengers handed over their lunches without argument.","base":12,"risk":3,"s":"You have the bees demand the mail too.","w":"You report the bees have taken over the stage line and are running it more punctually."},
  {"id":"h47","name":"The spirit photographer","text":"A photographer on C Street makes portraits that show the ghost of a dead relative standing behind the sitter, for three dollars extra.","base":17,"risk":12,"pay":true,"s":"You report that one sitter got the ghost of somebody else’s relative, and wants a refund.","w":"You report that a ghost in one portrait was recognised as the photographer’s brother-in-law, alive and well in Gold Hill."},
  {"id":"h48","name":"A volcano in Washoe?","text":"Smoke is rising from a hill east of Dayton. Ranchers fear a volcano. A geologist from San Francisco is on his way, slowly.","base":18,"risk":7,"s":"You report the hill has begun to rumble and the ranchers’ cows give warm milk.","w":"You report the volcano has erupted, covering the valley in silver ore, and the geologist is filing a claim."},
  {"id":"h49","name":"The giant trout of Tahoe","text":"A fisherman landed a trout so large it had to be hauled up the beach by a team of oxen.","base":13,"risk":3,"s":"You report the trout fought the oxen for an hour and nearly won.","w":"You report a smaller fisherman was found inside it, still fishing."},
  {"id":"h50","name":"The automaton chess player","text":"A mechanical Turk that plays chess has arrived at the International Hotel. It beat the mayor in eleven moves and a judge in seven.","base":15,"risk":9,"s":"You describe it cheating the judge, who is now hearing appeals in the matter.","w":"You report the machine was opened and found to contain a small, very good chess player from Sacramento who wants his wages."},
  {"id":"h51","name":"The barometer that predicts stocks","text":"A Gold Hill barber claims his barometer rises and falls with the price of Ophir feet. He has stopped cutting hair and started speculating.","base":13,"risk":10,"pay":true,"s":"You report brokers lining up at the barbershop for a glance.","w":"You report the barometer dropped, the market followed, and the barber was the only man in town who made money."},
  {"id":"h52","name":"A diamond in a chicken","text":"A cook on B Street cut open a chicken for dinner and found a diamond in its crop. Now every chicken in town is under suspicion.","base":16,"risk":5,"s":"You report a run on chickens at the market.","w":"You report a man is operating a chicken mine in Six-Mile Canyon and selling feet in it."},
  {"id":"h53","name":"The ventriloquist’s revenge","text":"A ventriloquist in town threw his voice into the jail and convinced the prisoners the sheriff had pardoned them all.","base":14,"risk":11,"s":"You report three prisoners left before the sheriff noticed.","w":"You report the ventriloquist made the courthouse statue testify, and it got off a man accused of horse theft."},
  {"id":"h54","name":"The wandering boulder","text":"A boulder the size of a wagon has moved forty feet across a dry lake bed since last month, and nobody has seen it go.","base":17,"risk":4,"s":"You report it moves only at night, and is headed for Carson City.","w":"You report it has been seen at the Carson City courthouse demanding citizenship."},
  {"id":"h55","name":"Professor Merrivale’s rain machine","text":"An inventor proposes to make rain on the alkali flats by firing cannon into the sky. He wants a public subscription and a great deal of gunpowder.","base":15,"risk":9,"s":"You report his first trial brought down a cloud of dust and a duck.","w":"You report it worked too well, and Washoe is now a lake with the inventor on a raft in the middle, selling dry land."},
];
